package com.gamingevents.controller;
import com.gamingevents.entity.*; import com.gamingevents.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/tournaments") @PreAuthorize("hasRole('ADMIN')") public class AdminTournamentController { final TournamentRepository tournaments; public AdminTournamentController(TournamentRepository t){tournaments=t;} @GetMapping public List<Map<String,Object>> list(){return tournaments.findAll().stream().map(t->Map.<String,Object>of("id",t.getId(),"name",t.getName(),"game",t.getGameName(),"status",t.getStatus().name(),"organizer",t.getOrganizer().getName())).toList();} @PutMapping("/{id}/approve") public void approve(@PathVariable Long id){var t=tournaments.findById(id).orElseThrow();t.setStatus(TournamentStatus.UPCOMING);tournaments.save(t);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){tournaments.deleteById(id);}}
